-- schema (order matters - customers/products before transactions before campaign_log, FKs)
CREATE TABLE IF NOT EXISTS clean_customers (
	customer_id VARCHAR NOT NULL, 
	email VARCHAR NOT NULL, 
	name VARCHAR NOT NULL, 
	age INTEGER NOT NULL, 
	gender VARCHAR, 
	country VARCHAR, 
	city VARCHAR, 
	phone_number VARCHAR, 
	interests VARCHAR, 
	signup_date DATE NOT NULL, 
	last_purchase_date DATE, 
	total_spent FLOAT, 
	purchase_frequency FLOAT, 
	churn INTEGER, 
	created_at TIMESTAMP WITHOUT TIME ZONE NOT NULL, 
	PRIMARY KEY (customer_id)
);
CREATE TABLE IF NOT EXISTS clean_products (
	product_id VARCHAR NOT NULL, 
	product_name VARCHAR NOT NULL, 
	category VARCHAR NOT NULL, 
	description VARCHAR, 
	price FLOAT NOT NULL, 
	stock_status VARCHAR NOT NULL, 
	created_at TIMESTAMP WITHOUT TIME ZONE DEFAULT now() NOT NULL, 
	PRIMARY KEY (product_id)
);
CREATE TABLE IF NOT EXISTS clean_transactions (
	transaction_id VARCHAR NOT NULL, 
	total_price FLOAT NOT NULL, 
	quantity INTEGER NOT NULL, 
	purchase_date TIMESTAMP WITHOUT TIME ZONE NOT NULL, 
	created_at TIMESTAMP WITHOUT TIME ZONE DEFAULT now() NOT NULL, 
	customer_id VARCHAR NOT NULL, 
	product_id VARCHAR NOT NULL, 
	PRIMARY KEY (transaction_id), 
	FOREIGN KEY(customer_id) REFERENCES clean_customers (customer_id), 
	FOREIGN KEY(product_id) REFERENCES clean_products (product_id)
);
CREATE TABLE IF NOT EXISTS campaign_log (
	log_id SERIAL NOT NULL, 
	customer_id VARCHAR NOT NULL, 
	campaign_id VARCHAR NOT NULL, 
	segment VARCHAR, 
	churn_score FLOAT, 
	template VARCHAR, 
	subject VARCHAR, 
	dry_run BOOLEAN NOT NULL, 
	sent_at TIMESTAMP WITHOUT TIME ZONE NOT NULL, 
	opened BOOLEAN, 
	clicked BOOLEAN, 
	PRIMARY KEY (log_id), 
	FOREIGN KEY(customer_id) REFERENCES clean_customers (customer_id)
);

